interface D { apply(t: number, extra: string[]): number }
class P implements D { apply(t: number) { return t * 2; } }
class Q implements D { apply(t: number): number { return t * 3; } }
interface Cb { run(a: number, b: string, c: boolean): string }
function main(): void {
  const d: D = new P();
  const q: D = new Q();
  const o: D = { apply: (t: number) => t * 4 };
  const cb: Cb = { run(a) { return "n" + a; } };
  console.log(d.apply(2, ["x"]), q.apply(2, ["y"]), o.apply(2, ["z"]), cb.run(1, "b", true));
}
